/bin/bash -lc "mkdir -p public data && cat > package.json <<'EOF'
{
  \"name\": \"reading-room\",
  \"version\": \"1.0.0\",
  \"private\": true,
  \"type\": \"module\",
  \"scripts\": {
    \"dev\": \"node server.js\",
    \"start\": \"node server.js\",
    \"build\": \"node --check server.js && node --check public/app.js\",
    \"test\": \"node --test\"
  }
}
EOF
cat > server.js <<'EOF'
import http from 'node:http';
import { readFile, writeFile, mkdir, rename } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));
const dataFile = process.env.BOOKS_FILE || path.join(root, 'data', 'books.json');
const port = Number(process.env.PORT) || 3000;
const host = process.env.HOST || '0.0.0.0';
let writeQueue = Promise.resolve();

async function readBooks() {
  try {
    const books = JSON.parse(await readFile(dataFile, 'utf8'));
    if ("'!Array.isArray(books)) throw new Error('"'Books data must be an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

function changeBooks(change) {
  const operation = writeQueue.then(async () => {
    const books = await readBooks();
    const result = change(books);
    await mkdir(path.dirname(dataFile), { recursive: true });
    const temp = "'`${dataFile}.${randomUUID()}.tmp`;
    await writeFile(temp, JSON.stringify(books, null, 2) + '"'\\n');
    await rename(temp, dataFile);
    return result;
  });
  writeQueue = operation.catch(() => {});
  return operation;
}

function send(res, status, body, type = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  res.end(type.startsWith('application/json') ? JSON.stringify(body) : body);
}

async function bodyJson(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 100_000) throw Object.assign(new Error('Request is too large'), { status: 413 });
  }
  try { return JSON.parse(body); } catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}

function validateText(value, label, max, required = false) {
  if (typeof value "'!== '"'string') throw Object.assign(new Error("'`${label} must be text`), { status: 400 });
  const text = value.trim();
  if (required && !text) throw Object.assign(new Error(`${label} is required`), { status: 400 });
  if (text.length > max) throw Object.assign(new Error(`${label} is too long`), { status: 400 });
  return text;
}

const mime = { '"'.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.svg': 'image/svg+xml' };
const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, "'`http://${req.headers.host || '"'localhost'}"'`);
    const pathname = url.pathname;
    if (pathname === '"'/api/books' && req.method === 'GET') return send(res, 200, await readBooks());
    if (pathname === '/api/books' && req.method === 'POST') {
      const input = await bodyJson(req);
      const book = {
        id: randomUUID(),
        title: validateText(input.title, 'Title', 200, true),
        author: validateText(input.author, 'Author', 200, true),
        notes: validateText(input.notes ?? '', 'Notes', 10000),
        status: input.status === 'finished' ? 'finished' : 'reading',
        createdAt: new Date().toISOString(),
        finishedAt: input.status === 'finished' ? new Date().toISOString() : null
      };
      await changeBooks(books => books.unshift(book));
      return send(res, 201, book);
    }
    const match = pathname.match(/"'^'"\\/api\\/books\\/([a-zA-Z0-9-]+)"'$/);
    if (match) {
      const id = match[1];
      if (req.method === '"'GET') {
        const book = (await readBooks()).find(item => item.id === id);
        return book ? send(res, 200, book) : send(res, 404, { error: 'Book not found' });
      }
      if (req.method === 'PATCH') {
        const input = await bodyJson(req);
        const book = await changeBooks(books => {
          const item = books.find(entry => entry.id === id);
          if ("'!item) throw Object.assign(new Error('"'Book not found'), { status: 404 });
          if ('title' in input) item.title = validateText(input.title, 'Title', 200, true);
          if ('author' in input) item.author = validateText(input.author, 'Author', 200, true);
          if ('notes' in input) item.notes = validateText(input.notes, 'Notes', 10000);
          if ('status' in input) {
            if ("'!['"'reading', 'finished'].includes(input.status)) throw Object.assign(new Error('Invalid status'), { status: 400 });
            if (item.status "'!== input.status) item.finishedAt = input.status === '"'finished' ? new Date().toISOString() : null;
            item.status = input.status;
          }
          return item;
        });
        return send(res, 200, book);
      }
      if (req.method === 'DELETE') {
        await changeBooks(books => {
          const index = books.findIndex(entry => entry.id === id);
          if (index === -1) throw Object.assign(new Error('Book not found'), { status: 404 });
          books.splice(index, 1);
        });
        return send(res, 200, { ok: true });
      }
    }
    if (pathname.startsWith('/api/')) return send(res, 404, { error: 'Not found' });
    if (req.method "'!== '"'GET' && req.method "'!== '"'HEAD') return send(res, 405, { error: 'Method not allowed' });
    let file = pathname === '/' || /"'^'"\\/books\\/["'^/]+'"\\/?"'$/.test(pathname) ? '"'index.html' : pathname.slice(1);
    if ("'!['"'index.html', 'styles.css', 'app.js'].includes(file)) return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
    const content = await readFile(path.join(root, 'public', file));
    res.writeHead(200, { 'Content-Type': mime[path.extname(file)], 'X-Content-Type-Options': 'nosniff' });
    res.end(req.method === 'HEAD' ? undefined : content);
  } catch (error) {
    console.error(error);
    send(res, error.status || 500, { error: error.status ? error.message : 'Something went wrong. Please try again.' });
  }
});
server.listen(port, host, () => console.log("'`Reading Room running at http://${host}:${port}`));
EOF
