/bin/bash -lc "cat > public/app.js <<'EOF'
const app = document.querySelector('#app');
const dialog = document.querySelector('#book-dialog');
const form = document.querySelector('#book-form');
const toast = document.querySelector('#toast');
let books = [];
let editingId = null;
let toastTimer;

const escapeHtml = value => String(value ?? '').replace(/[&<>\"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' })[character]);
const arrow = '<span aria-hidden=\"true\">↗</span>';
const bookIcon = '<svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"M4 5.5c2.8-1.1 5.4-.6 8 1.2v11.8c-2.6-1.8-5.2-2.3-8-1.2V5.5Zm16 0c-2.8-1.1-5.4-.6-8 1.2v11.8c2.6-1.8 5.2-2.3 8-1.2V5.5Z\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/></svg>';
const checkIcon = '<svg viewBox=\"0 0 20 20\" fill=\"none\" aria-hidden=\"true\"><path d=\"m4.5 10 3.5 3.5 7.5-7.5\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>';

async function api(url, options = {}) {
  const response = await fetch(url, { ...options, headers: { 'Content-Type': 'application/json', ...options.headers } });
  let result;
  try { result = await response.json(); } catch { throw new Error('Could not read the server response.'); }
  if ("'!response.ok) throw new Error(result.error || '"'Something went wrong.');
  return result;
}
function notify(message) {
  toast.textContent = message;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), 3000);
}
function colorFor(book) {
  const samples = { 'sample-creative-act': 0, 'sample-midnight-library': 1, 'sample-atomic-habits': 2, 'sample-alchemist': 3 };
  if (book.id in samples) return samples[book.id];
  return [...book.title].reduce((sum, character) => sum + character.charCodeAt(0), 0) % 4;
