/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const dir = await mkdtemp(path.join(os.tmpdir(), 'reading-room-'));
const file = path.join(dir, 'books.json');
const base = 'http://127.0.0.1:3124';
let server;
async function start() {
  server = spawn(process.execPath, ['server.js'], { env: { ...process.env, PORT: '3124', HOST: '127.0.0.1', BOOKS_FILE: file }, stdio: 'ignore' });
  for (let i = 0; i < 100; i++) {
    try { await fetch(base); return; } catch { await new Promise(resolve => setTimeout(resolve, 30)); }
  }
  throw new Error('Server did not start');
}
async function stop() { server.kill(); await new Promise(resolve => server.once('exit', resolve)); }
async function request(route, options = {}) {
  const response = await fetch(base + route, { ...options, headers: { 'content-type': 'application/json' } });
  return [response.status, await response.json()];
}
try {
  await start();
  assert.deepEqual((await request('/api/books'))[1], []);
  const [badStatus] = await request('/api/books', { method: 'POST', body: JSON.stringify({ title: '', author: 'Author' }) });
  assert.equal(badStatus, 400);
  const [createdStatus, created] = await request('/api/books', { method: 'POST', body: JSON.stringify({ title: 'A Book', author: 'An Author', notes: 'My notes' }) });
  assert.equal(createdStatus, 201);
  assert.equal(created.status, 'reading');
  const [updatedStatus, updated] = await request("'`/api/books/${created.id}`, { method: '"'PATCH', body: JSON.stringify({ status: 'finished' }) });
  assert.equal(updatedStatus, 200);
  assert.equal(updated.status, 'finished');
  assert.ok(updated.finishedAt);
  assert.equal((await fetch("'`${base}/books/${created.id}`)).status, 200);
  assert.equal(JSON.parse(await readFile(file, '"'utf8'))[0].notes, 'My notes');
  await stop();
  await start();
  assert.deepEqual((await request("'`/api/books/${created.id}`))[1], updated);
  const additions = await Promise.all(Array.from({ length: 10 }, (_, i) => request('"'/api/books', { method: 'POST', body: JSON.stringify({ title: "'`Book ${i}`, author: '"'Author' }) })));
  assert.ok(additions.every(([status]) => status === 201));
  assert.equal((await request('/api/books'))[1].length, 11);
  assert.equal((await request("'`/api/books/${created.id}`, { method: '"'DELETE' }))[0], 200);
  assert.equal((await request("'`/api/books/${created.id}`))[0], 404);
  console.log('"'Passed: validation, add, finish, share URL, persistence after restart, concurrent writes, and removal.');
} finally {
  if (server && server.exitCode === null) await stop();
  await rm(dir, { recursive: true, force: true });
}
EOF"

